// Maps {op, sync, ...} onto a framer-cms-sync route.
const b = $json.body || {};
const sync = encodeURIComponent(b.sync || 'blog');
const q = (o) => { const p = new URLSearchParams(Object.entries(o).filter(([, v]) => v !== undefined && v !== null && v !== '')); return p.toString() ? '?' + p : ''; };
const routes = {
  plan:      ['POST', `/syncs/${sync}/plan`],
  apply:     ['POST', `/syncs/${sync}/apply` + q({ planId: b.planId, publish: b.publish })],
  items:     ['GET',  `/syncs/${sync}/items`],
  remove:    ['DELETE', `/syncs/${sync}/items/${encodeURIComponent(b.slug || '')}` + q({ redirectTo: b.redirectTo, publish: b.publish })],
  redirects: ['GET',  '/redirects'],
  'redirects-plan':  ['POST', '/redirects/plan'],
  'redirects-apply': ['POST', '/redirects/apply' + q({ publish: b.publish })],
};
const r = routes[b.op];
if (!r) return [{ json: { method: 'GET', path: '/health', payload: {} } }];
return [{ json: { method: r[0], path: r[1], payload: b.payload ?? {} } }];
